    [Fact]public void CommittedPolicyAndAuditSurviveReopening(){var root=Root();Guid server;using(var store=ManagementStore.Initialize(root,"admin","TestPassword-123"))using(var host=Create(store)){server=store.InstanceId;using var operation=host.CreateSession(Identity(Admin)).BeginOperation();host.ApplyDatabaseChange(operation,RemoveReader(1));Assert.Equal(2,host.Policy.Version);Assert.Equal(2,host.History().Items.Length);Assert.True(host.ReadVersion(1).Policy.Restore().Resolve(Identity(User)).Evaluate(Table,SecurityPermission.Read).Allowed);Assert.False(host.ReadVersion(2).Policy.Restore().Resolve(Identity(User)).Evaluate(Table,SecurityPermission.Read).Allowed);var audit=store.AuditEvents(new(Action:AuditAction.PermissionChange));Assert.Equal(2,audit.Items.Length);var item=Assert.Single(audit.Items,item=>item.OperationId==operation.Audit.OperationId);Assert.Equal(operation.Audit.Subject.AuthorityId,item.AuthorityId);Assert.Equal(operation.Audit.Subject.Value,item.SubjectId);Assert.Equal(operation.Audit.PolicyVersion,item.PolicyVersion);}using var reopened=new ManagementStore(root);using var restored=StoredAuthorization.Open(reopened);Assert.Equal(server,restored.Policy.ServerId);using var denied=restored.CreateSession(Identity(User)).BeginOperation();Assert.Throws<AuthorizationException>(()=>denied.Demand(Table,SecurityPermission.Read));Assert.Equal(2,restored.History().Items.Length);}
    [Fact]public void TwoHostsDetectConflictsAndRefreshOnlyNewOperations(){using var store=ManagementStore.Initialize(Root(),"admin","TestPassword-123");using var first=Create(store);using var second=StoredAuthorization.Open(store);var user=second.CreateSession(Identity(User));using var active=user.BeginOperation();using var edit=first.CreateSession(Identity(Admin)).BeginOperation();using var stale=second.CreateSession(Identity(Admin)).BeginOperation();first.ApplyDatabaseChange(edit,RemoveReader(1));active.Demand(Table,SecurityPermission.Read);using(var next=user.BeginOperation()){Assert.Throws<AuthorizationException>(()=>next.Demand(Table,SecurityPermission.Read));Assert.Equal(2,next.Audit.PolicyVersion);}Assert.Equal("Conflict",Assert.Throws<AuthorizationException>(()=>second.ApplyDatabaseChange(stale,RemoveReader(1))).Code);Assert.Equal(2,second.Policy.Version);Assert.Equal(2,store.AuditEvents(new(Action:AuditAction.PermissionChange)).Items.Length);}
    [Fact]public void PreparedFailureRollsBackPolicyHistoryAndAudit(){using var store=ManagementStore.Initialize(Root(),"admin","TestPassword-123");using var host=Create(store);var revision=store.Revision;var catalog=store.CatalogRevision;using var operation=host.CreateSession(Identity(Admin)).BeginOperation();host.Checkpoint=phase=>{if(phase=="Prepared"){throw new IOException("injected before commit");}};Assert.Throws<IOException>(()=>host.ApplyDatabaseChange(operation,RemoveReader(1)));Assert.Equal(1,host.Policy.Version);Assert.Equal(revision,store.Revision);Assert.Equal(catalog,store.CatalogRevision);Assert.Single(host.History().Items);Assert.Single(store.AuditEvents(new(Action:AuditAction.PermissionChange)).Items);Assert.Null(host.FindOperation(operation.Audit.OperationId));Assert.Equal("NotFound",Assert.Throws<ManagementException>(()=>host.ReadVersion(2)).Code);}
