    [Fact]public void CancellationAtPreparedPointLeavesThePreviousPolicy(){using var store=ManagementStore.Initialize(Root(),"admin","TestPassword-123");using var host=Create(store);using var cancellation=new CancellationTokenSource();using var operation=host.CreateSession(Identity(Admin)).BeginOperation(cancellation.Token);host.Checkpoint=phase=>{if(phase=="Prepared"){cancellation.Cancel();}};Assert.ThrowsAny<OperationCanceledException>(()=>host.ApplyDatabaseChange(operation,RemoveReader(1)));Assert.Equal(1,host.Policy.Version);Assert.Single(host.History().Items);Assert.Single(store.AuditEvents(new(Action:AuditAction.PermissionChange)).Items);}
