    [Fact]public async Task ConcurrentHostsCommitOnlyOneChangeFromTheSameVersion(){using var store=ManagementStore.Initialize(Root(),"admin","TestPassword-123");using var first=Create(store);using var second=StoredAuthorization.Open(store);using var barrier=new Barrier(2);void Checkpoint(string phase){if(phase=="Saving"){Assert.True(barrier.SignalAndWait(TimeSpan.FromSeconds(20)));}}first.Checkpoint=Checkpoint;second.Checkpoint=Checkpoint;async Task<Exception?> Apply(StoredAuthorization host)=>await Task.Run(()=>{using var operation=host.CreateSession(Identity(Admin)).BeginOperation();try{host.ApplyDatabaseChange(operation,RemoveReader(1));return null;}catch(Exception error){return error;}});var results=await Task.WhenAll(Apply(first),Apply(second));Assert.Single(results,item=>item is null);Assert.Equal("Conflict",Assert.IsType<AuthorizationException>(Assert.Single(results,item=>item is not null)).Code);Assert.Equal(2,first.Policy.Version);Assert.Equal(2,second.Policy.Version);Assert.Equal(2,first.History().Items.Length);Assert.Equal(2,store.AuditEvents(new(Action:AuditAction.PermissionChange)).Items.Length);}
